/**
 * The KIND of calendar term. BAJC runs Summer and Spring blocks alongside its
 * numbered semesters — before D30, `semesters.sequence` was CHECK-constrained to
 * (1,2) and the school could not record a third term at all.
 *
 * NOT a curriculum position: "Semester 1" in a programme's PLAN is
 * `program_courses.term_label`, a different fact entirely (§D3).
 */
export const TermType = {
  summer: 'summer',
  semester: 'semester',
  spring: 'spring',
} as const;
export type TermType = (typeof TermType)[keyof typeof TermType];
